{$ param tab_1_label label="Tab 1 Label" default="Tab 1" description="First tab label (required)." $}
{$ param tab_2_label label="Tab 2 Label" default="Tab 2" description="Second tab label (leave blank to hide)." $}
{$ param tab_3_label label="Tab 3 Label" default="" description="Third tab label (leave blank to hide)." $}
{$ param tab_4_label label="Tab 4 Label" default="" description="Fourth tab label (leave blank to hide)." $}

<div class="w-full mx-auto mt-4 ss-tabs-wrap">
  <div class="tabs tabs-style2">
    <ul class="tab-links tabs-tabs flex border-b border-gray-200 mb-4 backport" role="tablist">
      {$ if tab_1_label $}<li class="tab-active" role="presentation"><a href="#ss-tab-1" class="px-4 py-2" role="tab" aria-selected="true" tabindex="0">{$= tab_1_label $}</a></li>{$ /if $}
      {$ if tab_2_label $}<li role="presentation"><a href="#ss-tab-2" class="px-4 py-2" role="tab" aria-selected="false" tabindex="-1">{$= tab_2_label $}</a></li>{$ /if $}
      {$ if tab_3_label $}<li role="presentation"><a href="#ss-tab-3" class="px-4 py-2" role="tab" aria-selected="false" tabindex="-1">{$= tab_3_label $}</a></li>{$ /if $}
      {$ if tab_4_label $}<li role="presentation"><a href="#ss-tab-4" class="px-4 py-2" role="tab" aria-selected="false" tabindex="-1">{$= tab_4_label $}</a></li>{$ /if $}
    </ul>
    <div class="tab-contents">
      {$ if tab_1_label $}<div id="ss-tab-1" class="p-4" role="tabpanel">{$ slot tab_1 $}<p>Tab 1 content.</p>{$ /slot $}</div>{$ /if $}
      {$ if tab_2_label $}<div id="ss-tab-2" class="p-4 hidden" role="tabpanel">{$ slot tab_2 $}<p>Tab 2 content.</p>{$ /slot $}</div>{$ /if $}
      {$ if tab_3_label $}<div id="ss-tab-3" class="p-4 hidden" role="tabpanel">{$ slot tab_3 $}<p>Tab 3 content.</p>{$ /slot $}</div>{$ /if $}
      {$ if tab_4_label $}<div id="ss-tab-4" class="p-4 hidden" role="tabpanel">{$ slot tab_4 $}<p>Tab 4 content.</p>{$ /slot $}</div>{$ /if $}
    </div>
  </div>
</div>

<script>
(function() {
  if (window.__ssTabsBound) return;
  window.__ssTabsBound = true;
  document.addEventListener('click', function(e) {
    var a = e.target.closest('.ss-tabs-wrap .tab-links a');
    if (!a) return;
    e.preventDefault();
    var wrap = a.closest('.ss-tabs-wrap');
    wrap.querySelectorAll('.tab-links li').forEach(function(li) { li.classList.remove('tab-active'); });
    a.parentElement.classList.add('tab-active');
    wrap.querySelectorAll('.tab-links a').forEach(function(x) { x.setAttribute('aria-selected', 'false'); x.setAttribute('tabindex', '-1'); });
    a.setAttribute('aria-selected', 'true');
    a.setAttribute('tabindex', '0');
    wrap.querySelectorAll('.tab-contents > div').forEach(function(p) { p.classList.add('hidden'); });
    var target = wrap.querySelector(a.getAttribute('href'));
    if (target) target.classList.remove('hidden');
  });
})();
</script>
